"""Further essays on questions from the project's original conversation."""
ESSAYS = [
dict(slug='obrazovanie-i-dobrota', title='Становится ли человек добрее, когда больше знает?', theme='Образование и совесть',
 lead='Очень хочется верить, что хорошее образование делает мир лучше. Но ведь умный человек тоже может быть жестоким. Чего же не хватает одним знаниям?',
 lens='Христианский взгляд · Ответственность за знание · Школа и литература', art='mental-count', art_title='Дети, которые думают',
 art_text='<p>На картине Богданова-Бельского ученики решают одну задачу. Кто-то уже близок к ответу, кто-то ещё всматривается в доску. У каждого своё лицо, своё усилие. Эта картина здесь — образ школы, в которой за общим делом виден отдельный ребёнок.</p>',
 sections=[
 ('Знание даёт человеку больше возможностей','<p>Образование многое меняет. Мы лучше понимаем сложные тексты, можем проверить расчёт, заметить ошибку, задать вопрос тому, кто говорит уверенно. Нам становятся доступны занятия, о которых раньше мы даже не знали.</p><p>Но знания можно использовать по-разному. Понимая чужую слабость, один человек поможет, а другой обманет. Поэтому вместе с вопросом «чему учиться?» появляется ещё один: для чего мне эти знания? Что я буду с ними делать?</p>'),
 ('Что об этом говорит литература','<p>В «Уроках французского» мальчику нужно не только учиться, но и есть. Лидия Михайловна замечает его беду. Но как помочь ученику, который стесняется принимать помощь? Она ищет способ поддержать его и сберечь его достоинство.</p><p>В «Недоросле» учителя наняты, занятия идут, а отношение к людям в доме остаётся жестоким. Чему научится ребёнок, если каждый день видит, как сильный унижает слабого? Одних уроков здесь явно недостаточно.</p><p>В этих историях школа и герои разные. Но вопрос у нас возникает общий: ради чего мы учим? Чтобы ребёнок действительно рос и развивался — или чтобы хорошо выглядели отметки и отчёты?</p>'),
 ('Можно ли записать доброту формулой?','<p>Иногда хочется представить простую зависимость: больше знаний — больше добра. Для такой формулы пришлось бы сначала договориться, что именно мы измеряем. Число прочитанных книг? Результат экзамена? Готовность прийти на помощь? Уже здесь видно, что речь идёт о разных вещах.</p><p>Мы рассуждаем о значении слов, а не приводим результаты психологического исследования. Высокий балл показывает, как человек справился с заданием. По нему нельзя узнать, как он обращается с близкими и готов ли помочь незнакомому.</p><p>Математическая точность всё же полезна. Она приучает видеть, где есть основание для ответа, где допущение, а где мы просто очень хотим, чтобы получилось именно так. Такая честность нужна и в разговоре о людях.</p>'),
 ('Чему можно учить собственным примером','<p>Христианский взгляд побуждает спросить, как наше решение отразится на ближнем. Мы действительно ему помогаем? Выслушали его? Или назвали заботой своё желание всё решить за него?</p><p>В школе это начинается с простых поступков. Признать перед учеником свою ошибку. Дослушать ответ. Объяснить ещё раз, не стыдя за непонимание. Так ребёнок узнаёт, что умный человек может быть терпеливым и внимательным.</p><p>Наверное, поэтому образование и даёт надежду. Мы передаём не только знания, но и собственный способ обращаться с людьми.</p>')],
 quote='darenie', quote_comment='Присвоить весь успех себе очень легко. Память об учителях, близких и полученной помощи возвращает знание в отношения между людьми.',
 extra_quotes=['pamyat-o-slabosti'], music=[('cello','Негромкая сарабанда Баха сопровождает размышление об учёбе и внимании. Здесь можно просто побыть рядом с прочитанным.')],
 prompt='Достаточно ли образованности, чтобы быть нравственным человеком?', writing='Возьмите один эпизод, в котором герой проявляет знания, и другой, где ему приходится выбирать способ обращения с человеком. Совпадают ли в этих эпизодах ум и доброта? Из этого различия может вырасти ваш собственный тезис.',
 books=[('uroki-frantsuzskogo-dostoinstvo','Валентин Распутин. «Уроки французского»','как помочь ученику и сохранить его достоинство?'),('nedorosl','Денис Фонвизин. «Недоросль»','что происходит с образованием в доме, где привыкли унижать людей?')],
 sources=[('https://ilibrary.ru/text/1098/p.1/index.html','Д. И. Фонвизин. «Недоросль»','Литературная опора; анализ поступков и устройства воспитания.'),('/masterskaya/uroki-frantsuzskogo-dostoinstvo/','Разбор «Уроков французского» и первоисточники','Подробный разговор о помощи и достоинстве ученика.')]),

dict(slug='dobro-i-zhestokost',title='Как защищать добро и не привыкнуть к жестокости',theme='Сопротивление злу',
 lead='Когда видишь несправедливость, хочется, чтобы её наконец остановили. Но что происходит с нами самими, пока мы боремся?',
 lens='Христианская этика · Литературный поступок · Цель и средства',art='truth-pilate',art_title='Истина перед лицом власти',
 art_text='<p>На картине Николая Ге Пилат стоит в ярком свете, Христос — в тени. Их встреча сопровождает разговор об истине и решении человека, у которого есть власть. Художественный свет здесь не равен нравственной правоте.</p>',
 sections=[
 ('Желание остановить зло понятно','''<p>Свидетель чужого унижения не обязан делать вид, что ничего не случилось. Встать рядом с пострадавшим, назвать ложь ложью, добиваться прекращения жестокости — всё это требует сил. Мирное отношение к человеку не означает согласия с тем, что он делает.</p><p>Трудность начинается там, где чувство правоты разрешает уже всё. Мы перестаём спрашивать о цене своих действий, потому что заранее уверены в благой цели. Чужая боль начинает казаться заслуженной. В такой момент особенно нужен вопрос: кого мы сейчас защищаем и что именно прекращаем?</p>'''),
 ('Почему так тяжело читать «После бала»','<p>На балу полковник — любящий отец. Его танец с дочерью трогает Ивана Васильевича. Утром тот же полковник руководит жестоким наказанием солдата. Обе сцены относятся к одному человеку. Одну из них нельзя просто отбросить, чтобы нам было легче его оценить.</p><p>Иван Васильевич узнаёт человека, которым недавно восхищался. Оказывается, хорошие манеры и нежность к дочери могут соседствовать с жестокостью. Значит, по обаянию человека ещё нельзя судить обо всех его поступках.</p><p>Здесь возникает неприятный вопрос и к себе: чего мы не хотим замечать в людях, которые нам нравятся? Готовы ли признать их неправоту, даже если они принадлежат к нашему кругу?</p>'),
 ('Почему важна не только цель','<p>Допустим, мы хотим добиться согласия, но для этого унижаем человека. Он уступил — можно объявить успех. Только унижение никуда не исчезло. Оно останется в его памяти и повлияет на дальнейшие отношения.</p><p>В «Сигнале» Гаршина Семён пытается спасти поезд от последствий чужого гнева. У пассажиров своя жизнь. Они не должны расплачиваться за обиды Василия и его конфликт с начальством.</p><p>Универсального решения на все случаи здесь нет. Но есть полезный вопрос: кто может пострадать от того, что я собираюсь сделать? Не пропустил ли я этих людей, рассуждая о справедливости?</p>'),
 ('Уметь вовремя остановиться','<p>Православная мысль о покаянии относится и к тому, кто защищает правое дело. Можно быть правым в цели и ошибаться в поступках. Признать эту ошибку — значит получить возможность остановить причиняемый вред.</p><p>Учителю, родителю, руководителю важно иметь рядом человека, который не побоится возразить. И ещё важнее — суметь услышать: «Ты сейчас поступаешь жестоко».</p><p>Это трудно, особенно когда чувствуешь себя безусловно правым. Но такая готовность выслушать другого помогает заметить собственную жестокость, пока она не вошла в привычку.</p>')],
 quote='peremena',quote_comment='Нравственный выбор не закреплён за человеком раз и навсегда. Возможность измениться оставляет надежду и требует внимательности к себе.',extra_quotes=['smirenie-protiv-gordosti'],
 music=[('bach','Ария Erbarme dich сопровождает тему раскаяния и милости. Голос звучит без торжества над побеждённым.')],
 prompt='Может ли уверенность в доброй цели сделать человека жестоким?',writing='Начните с поступка, а не с общей оценки героя. Назовите его цель, избранное средство и того, кого затронули последствия. Затем покажите, какую из этих сторон рассказ делает особенно заметной.',
 books=[('posle-bala-uvidet-nasilie','Лев Толстой. «После бала»','зачем читателю нужно увидеть одного человека и на балу, и утром?'),('signal-prekratit-zlo','Всеволод Гаршин. «Сигнал»','как внимание к чужой жизни меняет ход конфликта?')],
 sources=[('/masterskaya/posle-bala-uvidet-nasilie/','«После бала»: разбор и первоисточник','Контраст сцен и перемена восприятия рассказчика.'),('/masterskaya/signal-prekratit-zlo/','«Сигнал»: разбор и первоисточник','Конкретная жизнь перед лицом чужого гнева.'),('https://www.pravmir.ru/o-nasilii/','Митрополит Антоний Сурожский. «О насилии»','Дополнительное авторское размышление; цитаты из этой публикации в святоотеческий корпус не перенесены.')]),

dict(slug='toska-po-miru',title='Чего нам не хватает, когда мы тоскуем по миру',theme='Замысел проекта',
 lead='Иногда кажется, что тоска по миру достигает космических масштабов. Хочется просто жить, читать, разговаривать с близкими. Почему это простое желание оказывается таким большим?',
 lens='Христианская надежда · Дом и близость · Литература как встреча',art='philosophers',art_title='Идти рядом',
 art_text='<p>«Философы» Нестерова возвращают к самому началу проекта. Два человека идут рядом, каждый со своим лицом и своей мыслью. Так может выглядеть разговор: общая дорога оставляет место двум разным людям.</p>',
 sections=[
 ('Какого мира нам хочется','<p>Мы тоскуем по миру, когда устаём от вражды. Но одной тишины бывает мало. Человек может молчать от страха или жить спокойно и очень одиноко. Хочется, чтобы рядом с другими можно было говорить, доверять и оставаться собой.</p><p>Дом, дорога, письмо, голос близкого кажутся небольшими вещами на фоне истории. Но из них и складывается наша жизнь. Книги помогают заметить, как много они для нас значат.</p>'),
 ('Книга помогает увидеть другого','<p>В «Станционном смотрителе» Дуня возвращается слишком поздно: отца уже нет. Их несостоявшийся разговор читателю остаётся только воображать. Мы знаем не всё, чтобы уверенно судить обоих. Но отцовское горе и дочернее раскаяние требуют внимания.</p><p>В «Юшке» окружающие долго видят лишь странного, безответного человека. О том, что он помогал девочке-сироте учиться, они узнают после его смерти. Тогда его жизнь и прежние эпизоды рассказа открываются нам по-другому.</p><p>Обе истории побуждают внимательнее смотреть на тех, кто рядом. Чтение само по себе не делает нас добрее. Но оно может удержать от поспешного суждения: а всё ли я знаю об этом человеке?</p>'),
 ('Надежда не обязана быть громкой','<p>Христианская надежда допускает слёзы, растерянность и ожидание. Она не требует от человека каждое утро выглядеть победителем. Иногда надежда сохраняется в очень небольшом действии: ответить на письмо, приготовить еду, прийти к тому, кто остался один.</p><p>У такого действия есть предел. Оно не устраняет всю несправедливость и не возвращает утраченное. Но для человека, к которому пришли, оно всё равно может оказаться важным. Даже небольшая помощь бывает очень нужна.</p><p>Поэтому нам нужна точность и в словах о добре. Если мы обещаем слишком много, потом легко решить, что всё было напрасно. Если говорим о сделанном прямо, видим его смысл: в этот день одному человеку было чуть менее одиноко.</p>'),
 ('Зачем этот сайт','<p>Здесь можно готовиться к сочинению. А можно читать и думать о том, что волнует нас вне экзаменов. Что такое милосердие? Почему трудно простить? Как сохранить убеждения и при этом услышать другого человека?</p><p>Основа этого разговора — православный взгляд на человека. Мы обращаемся к словам духовных авторов, читаем книги, рассматриваем картины, слушаем музыку. Всё это помогает обдумать прочитанное, а иногда — просто побыть с ним.</p><p>Мне хочется, чтобы у ученика появилась собственная мысль. Чтобы он мог сказать, что понял в книге, какой поступок его тронул и с чем он не согласен. Ради этого и существует «Узел тоски по миру».</p>')],
 quote='skorbi',quote_comment='Скрытая от нас скорбь не становится от этого менее настоящей. Эта короткая мысль помогает начать разговор о внимании к человеку.',extra_quotes=['mir-pered-molitvoy'],
 music=[('vigil','«Ныне отпущаеши» Рахманинова сопровождает тему ожидания и покоя. Песнопение сохраняет свой евангельский смысл, а здесь становится музыкальной иллюстрацией к размышлению.')],
 prompt='Почему человеку важно не чувствовать себя одиноким?',writing='Выберите эпизод, в котором присутствие другого что-то меняет. Это может быть поступок, разговор или позднее узнавание чужой заботы. Покажите, что именно изменилось, не обещая, что одна встреча разрешила всю жизнь героя.',
 books=[('yushka-nevidimoe-dobro','Андрей Платонов. «Юшка»','почему значение чужой заботы становится понятно так поздно?'),('smotritel-vozvrashchenie','Александр Пушкин. «Станционный смотритель»','что возвращение способно изменить, а что уже остаётся невозвратимым?')],
 sources=[('/masterskaya/yushka-nevidimoe-dobro/','«Юшка»: разбор и первоисточники','Скрытая забота и позднее узнавание.'),('/masterskaya/smotritel-vozvrashchenie/','«Станционный смотритель»: разбор и первоисточники','Разлука, возвращение и границы читательского суждения.'),('https://tretyakovgallerymagazine.ru/articles/1-2013-38/nesterov-portretist','«Нестеров-портретист»','Материал о художественном контексте картины «Философы».')]),
]
